// Build one Slack message from the jobs that are new since the last run.
const jobs = $input.all().map(i => i.json);

// Newest first.
jobs.sort((a, b) => String(b.publishedAt || '').localeCompare(String(a.publishedAt || '')));

// Slack will render a single long message, but nobody reads 80 lines.
const MAX_LINES = 25;
const shown = jobs.slice(0, MAX_LINES);

const clean = (s) => String(s ?? '').replace(/[<>&]/g, ' ').trim();

const lines = shown.map((j) => {
  const meta = [
    clean(j.company),
    clean(j.location),
    clean(j.jobType).replace(/_/g, ' '),
    clean(j.salary),
  ].filter(Boolean).join('  |  ');
  return `- <${j.url}|${clean(j.title) || 'Untitled role'}>\n   ${meta}`;
});

const header = `*${jobs.length} new remote ${jobs.length === 1 ? 'job' : 'jobs'}*`;
const trimmed = jobs.length - shown.length;
const footer = trimmed > 0
  ? `\n\n_+${trimmed} more matched today and were trimmed here to keep the message readable._`
  : '';

return [{ json: { text: `${header}\n\n${lines.join('\n')}${footer}`, count: jobs.length } }];
